/* DigiGlide page hooks (the SYN pages of every synth machine, types 0..3): three more pages on the active track, and
 * knob rows for DigiGlide's records (entries 321..338, past the 68-byte companion table, which cannot move). The
 * tables these use (dg_pages, dg_rows) are generated by build_dg.py into ptable.S. Every stub keeps the stock
 * reader's register use: d0 / d1 / a0 / a1 are scratch at all sites.
 * Stock's table 0x42432ad4 (1.11) holds 16 bytes a type: the page count, then the descriptors' address. */
    .text

/* 0x400c24d2 pages(type): jsr here over `moveq #4,%d1 ; move.l 4(%sp),%d0`. Stack: our return into the reader,
 * the caller's return, the type. The active track's own machine: stock count + 3, straight back to the caller. */
    .globl  dg_count_stub
dg_count_stub:
    move.l  8(%sp),%d0
    moveq   #3,%d1
    cmp.l   %d0,%d1
    bcs.s   1f
    move.l  %d0,-(%sp)
    jsr     dg_ui_active
    addq.l  #4,%sp
    tst.l   %d0
    beq.s   1f
    move.l  8(%sp),%d0
    lsl.l   #4,%d0
    lea     OSA_42432AD4,%a0
    move.l  (%a0,%d0.l),%d0
    addq.l  #4,%d0                  /* build 29: four pages */
    addq.l  #4,%sp
    rts
1:  moveq   #4,%d1
    move.l  8(%sp),%d0
    rts

/* 0x400c24ee page(type, n): jsr here at 0x400c24f2 over `move.l 8(%sp),%d1 ; move.l 12(%sp),%d0` (+ nop). Stack: our
 * return, the reader's saved d2, the caller's return, the type, the page. Page n >= the machine's own count on the
 * active track: our descriptor n - count, d2 restored, straight back to the caller. */
    .globl  dg_page_stub
dg_page_stub:
    move.l  12(%sp),%d0
    moveq   #3,%d1
    cmp.l   %d0,%d1
    bcs.s   1f
    lsl.l   #4,%d0
    lea     OSA_42432AD4,%a0
    move.l  16(%sp),%d1
    sub.l   (%a0,%d0.l),%d1
    bmi.s   1f
    moveq   #4,%d0
    cmp.l   %d0,%d1
    bge.s   1f
    move.l  %d1,-(%sp)
    move.l  16(%sp),-(%sp)
    jsr     dg_ui_active
    addq.l  #4,%sp
    move.l  (%sp)+,%d1
    tst.l   %d0
    beq.s   1f
    mulu.w  #44,%d1
    add.l   #dg_pages,%d1
    move.l  %d1,%d0
    addq.l  #4,%sp
    move.l  (%sp)+,%d2
    rts
1:  move.l  12(%sp),%d1
    move.l  16(%sp),%d0
    rts

/* 0x400c2418 companion row(entry): jsr here over `move.l 4(%sp),%d0 ; cmpi.l #321,%d0` (+ 2 nops). Stack: our return,
 * the caller's return, the entry. Entries 321..338: dg_row(entry - 321), a copy of a stock row that cannot be
 * p-locked or randomised (ui/dg_ui.c), straight back. Otherwise the displaced compare, whose carry the stock `scs`
 * after the nops reads (rts and nop keep the CCR). */
    .globl  dg_row_stub
dg_row_stub:
    move.l  8(%sp),%d0
    cmpi.l  #347,%d0                /* 321..346: 26 records (build 29) */
    bcc.s   1f
    cmpi.l  #321,%d0
    bcs.s   1f
    subi.l  #321,%d0
    move.l  %d0,-(%sp)
    jsr     dg_row
    addq.l  #8,%sp
    rts
1:  cmpi.l  #321,%d0
    rts

/* 0x40018118, the SYN page draw (view, canvas): jsr here over its first two instructions, `lea -28(%sp),%sp ;
 * movem.l %d2-%d4/%a2-%a4,(%sp)` (8 bytes; + nop). Each machine draws its pages its own way from here (FM TONE's
 * algorithm, FM DRUM's and SWARMER's extras), so DigiGlide's pages are taken before any of that:
 * dg_syn_draw(view, canvas) draws a DigiGlide page and returns 1 (straight back to the caller), or returns 0 and
 * the displaced instructions run. Stack: our return, the caller's return, the view, the canvas. */
    .globl  dg_syn_stub
dg_syn_stub:
    move.l  12(%sp),-(%sp)
    move.l  12(%sp),-(%sp)
    jsr     dg_syn_draw
    addq.l  #8,%sp
    tst.l   %d0
    beq.s   1f
    addq.l  #4,%sp
    rts
1:  move.l  (%sp)+,%a0
    lea     -28(%sp),%sp
    movem.l %d2-%d4/%a2-%a4,(%sp)
    jmp     (%a0)

/* 0x4011d398, the end of the screen pass: `clr.b %d0 ; move.b %d0,32(%a2)` (6 bytes, d0/d1/a0/a1 free) -> jsr here.
 * a2 = the screen, d3 = the canvas every layer drew on. dg_overlay(screen, canvas) acts on the DigiGlide shortcut and
 * draws its message last; then the displaced instructions clear the screen's "redraw due" flag as stock does. */
    .globl  dg_pass_stub
dg_pass_stub:
    move.l  %d3,-(%sp)
    move.l  %a2,-(%sp)
    jsr     dg_overlay
    addq.l  #8,%sp
    clr.b   %d0
    move.b  %d0,32(%a2)
    rts

/* 0x4004f8fe, the track context's "set lock" (ctx, step, slot, value): jsr here over `move.l %a2,-(%sp) ;
 * move.l %d2,-(%sp) ; movea.l 12(%sp),%a2` (8 bytes; + nop). Stack: our return, the caller's return, ctx, step,
 * slot, value. dg_lock_set_hook takes a DigiGlide row's lock (-> its result, straight back to the caller) or
 * returns 0x7fffffff: then the displaced instructions run under our return address. */
    .globl  dg_lockset_stub
dg_lockset_stub:
    move.l  20(%sp),-(%sp)
    move.l  20(%sp),-(%sp)
    move.l  20(%sp),-(%sp)
    move.l  20(%sp),-(%sp)
    jsr     dg_lock_set_hook
    lea     16(%sp),%sp
    cmpi.l  #0x7fffffff,%d0
    beq.s   1f
    addq.l  #4,%sp
    rts
1:  move.l  (%sp)+,%a0
    move.l  %a2,-(%sp)
    move.l  %d2,-(%sp)
    movea.l 12(%sp),%a2
    jmp     (%a0)

/* 0x4004f944, the track context's "remove lock" (ctx, step, slot): what a knob pushed with a step held ends in when
 * the step has the lock (0x400647d4 -> 0x40038018). The same first instructions as "set lock". */
    .globl  dg_lockclr_stub
dg_lockclr_stub:
    move.l  16(%sp),-(%sp)
    move.l  16(%sp),-(%sp)
    move.l  16(%sp),-(%sp)
    jsr     dg_lock_clr_hook
    lea     12(%sp),%sp
    cmpi.l  #0x7fffffff,%d0
    beq.s   1f
    addq.l  #4,%sp
    rts
1:  move.l  (%sp)+,%a0
    move.l  %a2,-(%sp)
    move.l  %d2,-(%sp)
    movea.l 12(%sp),%a2
    jmp     (%a0)

/* 0x4004eaa4, the track context's "get lock" (ctx, step, slot) -> value or -1: jsr here over `movea.l 4(%sp),%a0 ;
 * move.l 44(%a0),%d0` (8 bytes; + nop). Stack: our return, the caller's return, ctx, step, slot. */
    .globl  dg_lockget_stub
dg_lockget_stub:
    move.l  16(%sp),-(%sp)
    move.l  16(%sp),-(%sp)
    move.l  16(%sp),-(%sp)
    jsr     dg_lock_get_hook
    lea     12(%sp),%sp
    cmpi.l  #0x7fffffff,%d0
    beq.s   1f
    addq.l  #4,%sp
    rts
1:  move.l  (%sp)+,%a1
    movea.l 4(%sp),%a0
    move.l  44(%a0),%d0
    jmp     (%a1)
